// Tema de cores centralizado para o CashPilot
export const COLORS = {
  // Backgrounds
  background: '#0f172a',
  backgroundSecondary: '#1e293b',
  backgroundAccent: '#334155',

  // Textos
  text: '#f8fafc',
  textSecondary: '#cbd5e1',
  textMuted: '#64748b',

  // Accent / Primary
  accent: '#38bdf8',
  accentHover: '#0ea5e9',
  accentLight: '#7dd3fc',

  // Status
  success: '#10b981',
  warning: '#f59e0b',
  error: '#ef4444',

  // Cards
  cardBackground: 'rgba(30, 41, 59, 0.8)',
  cardBorder: 'rgba(51, 65, 85, 0.5)',

  // Gradientes
  gradientPrimary: 'linear-gradient(135deg, #0f172a 0%, #1e293b 100%)',
  gradientAccent: 'linear-gradient(135deg, #38bdf8 0%, #0ea5e9 100%)',

  // Bordas e sombras
  border: '#334155',
  shadow: 'rgba(0, 0, 0, 0.3)',
};

// Cores específicas para categorias (fallback)
export const CATEGORY_COLORS = [
  '#38bdf8', // Azul
  '#10b981', // Verde
  '#f59e0b', // Amarelo
  '#ef4444', // Vermelho
  '#8b5cf6', // Roxo
  '#f97316', // Laranja
  '#06b6d4', // Ciano
  '#84cc16', // Lima
  '#ec4899', // Rosa
  '#6b7280', // Cinza
];
